Tag = libsodium_crypto_auth:crypto_auth(<<"message">>, Key),
0 = libsodium_crypto_auth:verify(Tag, <<"message">>, Key),
-1 = libsodium_crypto_auth:verify(Tag, <<"forged">>, Key).
